            {/* Admin Tools - Only show for admin users */}
            {user?.role === 'admin' && (
              <>
                <div className="pt-4 mt-4 border-t">
                  <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2 px-2">
