                  </Button>
                  <Button
                    variant="ghost"
                    className="w-full justify-start"
                    onClick={() => setLocation('/crm/integrations')}
                  >
                    <Key className="mr-2 h-4 w-4" />
                    Integration Settings
                  </Button>
                </div>
              </>
            )}
          </nav>
        </aside>

        {/* Main Content */}
        <main className="flex-1 p-6">
          {activeTab === 'overview' && (
            <div className="space-y-6">
              <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold">Dashboard Overview</h2>
                <Button>
                  <Plus className="mr-2 h-4 w-4" />
                  Add Property
                </Button>
              </div>

              {/* Stats Grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatsCard 
                  title="Active Listings" 
                  value="156" 
                  change={12}
                  icon={Home}
                  color="bg-[#791E75] text-white 500"
                />
                <StatsCard 
                  title="This Month Sales" 
                  value="23" 
                  change={8}
                  icon={DollarSign}
                  color="bg-[#791E75] text-white 500"
                />
                <StatsCard 
                  title="Open Tickets" 
                  value="47" 
                  change={-5}
                  icon={AlertCircle}
                  color="bg-[#F8B324] text-black 500"
                />
                <StatsCard 
                  title="Total Staff" 
                  value="–" 
                  change={0}
                  icon={Users}
                  color="bg-purple-500"
                />
              </div>

              {/* Recent Activities */}
              <Card>
                <CardHeader>
                  <CardTitle>Recent Activities</CardTitle>
                  <CardDescription>Latest updates across the system</CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    {[
                      { icon: Home, text: "New property listed: 2 Bed Flat in Maida Vale", time: "2 hours ago", color: "text-[#791E75]600" },
                      { icon: CheckCircle, text: "Maintenance ticket #234 resolved", time: "3 hours ago", color: "text-[#791E75]600" },
                      { icon: Users, text: "New tenant registered: Sarah Johnson", time: "5 hours ago", color: "text-[#791E75]" },
                      { icon: DollarSign, text: "Property sale completed: 3 Bed House in Queens Park", time: "1 day ago", color: "text-[#F8B324]600" },
                    ].map((activity, i) => (
                      <div key={i} className="flex items-center space-x-4">
                        <activity.icon className={`h-5 w-5 ${activity.color}`} />
                        <div className="flex-1">
                          <p className="text-sm">{activity.text}</p>
                          <p className="text-xs text-gray-500">{activity.time}</p>
                        </div>
                      </div>
