import { PropertyValuationFormData } from '@shared/schema';

// Icons
import { 
  CheckCircle2, 
  Clock,
  PoundSterling,
  ShieldCheck,
  Home,
  Briefcase,
  Users,
  BarChart,
  ArrowRight,
  HeartHandshake,
