    let baseValue = 0;

    // Base value by property type
    switch (propertyType) {
      case 'detached':
        baseValue = 350000;
        break;
      case 'semi-detached':
        baseValue = 275000;
        break;
      case 'terraced':
        baseValue = 225000;
        break;
      case 'flat':
        baseValue = 200000;
        break;
      case 'bungalow':
        baseValue = 300000;
        break;
      default:
        baseValue = 250000;
    }

    // Adjust for bedrooms
    let bedroomMultiplier = 1.0;
    switch (bedrooms) {
      case '1':
        bedroomMultiplier = 0.8;
        break;
      case '2':
        bedroomMultiplier = 1.0;
        break;
      case '3':
        bedroomMultiplier = 1.2;
        break;
      case '4':
        bedroomMultiplier = 1.4;
        break;
      case '5+':
        bedroomMultiplier = 1.6;
        break;
    }

    // Adjust for condition
    let conditionMultiplier = 1.0;
    switch (condition) {
      case 'good':
        conditionMultiplier = 1.1;
        break;
      case 'average':
        conditionMultiplier = 1.0;
        break;
      case 'needs_work':
        conditionMultiplier = 0.85;
        break;
    }

    return Math.floor(baseValue * bedroomMultiplier * conditionMultiplier);
