export default function ReportBuilder() {
  const { toast } = useToast();
  const [activeTab, setActiveTab] = useState('reports');
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);

  const [reportForm, setReportForm] = useState({
    name: '',
    description: '',
    reportType: '',
    format: 'pdf',
    dateRange: '30',
    customStartDate: '',
    customEndDate: '',
    selectedMetrics: [] as string[],
    isScheduled: false,
    frequency: 'monthly',
    recipients: ''
  });

  const handleCreateReport = () => {
    if (!reportForm.name) {
      toast({
        title: 'Name required',
        description: 'Please enter a name for the report.',
        variant: 'destructive'
      });
      return;
    }

    toast({
      title: 'Report created',
      description: `"${reportForm.name}" has been created successfully.`
    });
    setShowCreateDialog(false);
    setSelectedTemplate(null);
    setReportForm({
      name: '',
      description: '',
      reportType: '',
      format: 'pdf',
      dateRange: '30',
      customStartDate: '',
      customEndDate: '',
      selectedMetrics: [],
      isScheduled: false,
      frequency: 'monthly',
      recipients: ''
    });
  };

  const handleGenerateReport = (report: any) => {
    toast({
      title: 'Generating report',
      description: `"${report.name}" is being generated. It will download shortly.`
    });
  };

  const handleRunNow = (report: any) => {
    toast({
      title: 'Running report',
      description: `"${report.name}" is being generated and will be sent to recipients.`
    });
  };

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-GB', {
      day: 'numeric',
      month: 'short',
      year: 'numeric'
    });
  };

  const toggleMetric = (metricId: string) => {
    if (reportForm.selectedMetrics.includes(metricId)) {
      setReportForm({
        ...reportForm,
        selectedMetrics: reportForm.selectedMetrics.filter(m => m !== metricId)
      });
    } else {
      setReportForm({
        ...reportForm,
        selectedMetrics: [...reportForm.selectedMetrics, metricId]
      });
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm border-b">
        <div className="px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-4">
              <Link href="/portal">
                <Button variant="ghost" size="icon" data-testid="button-back-to-portal">
                  <ArrowLeft className="h-5 w-5" />
                </Button>
              </Link>
              <FileText className="h-8 w-8 text-[#791E75] mr-3" />
              <h1 className="text-xl font-semibold">Report Builder</h1>
            </div>
            <div className="flex items-center space-x-4">
              <Dialog open={showCreateDialog} onOpenChange={setShowCreateDialog}>
                <DialogTrigger asChild>
                  <Button size="sm">
                    <Plus className="h-4 w-4 mr-2" />
                    New Report
                  </Button>
                </DialogTrigger>
                <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                  <DialogHeader>
                    <DialogTitle>Create New Report</DialogTitle>
                    <DialogDescription>
                      Choose a template or build a custom report
                    </DialogDescription>
                  </DialogHeader>

                  {!selectedTemplate ? (
                    <div className="grid grid-cols-2 gap-4">
                      {reportTemplates.map((template) => {
                        const IconComponent = template.icon;
                        return (
                          <div
                            key={template.id}
                            className="p-4 border rounded-lg cursor-pointer hover:border-blue-500 hover:bg-blue-50 transition-colors"
                            onClick={() => {
                              setSelectedTemplate(template.id);
                              setReportForm({ ...reportForm, reportType: template.id });
                            }}
                          >
                            <div className="flex items-center space-x-3 mb-2">
                              <IconComponent className="h-5 w-5 text-gray-600" />
                              <span className="font-medium">{template.name}</span>
                            </div>
                            <p className="text-sm text-gray-500">{template.description}</p>
                          </div>
                        );
                      })}
                    </div>
                  ) : (
                    <div className="space-y-4">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => setSelectedTemplate(null)}
                      >
                        ← Back to templates
                      </Button>

                      <div className="space-y-2">
                        <Label>Report Name</Label>
                        <Input
                          placeholder="e.g., Monthly Performance Report"
                          value={reportForm.name}
                          onChange={(e) => setReportForm({ ...reportForm, name: e.target.value })}
                        />
                      </div>

                      <div className="space-y-2">
                        <Label>Description</Label>
                        <Input
                          placeholder="Brief description of this report"
                          value={reportForm.description}
                          onChange={(e) => setReportForm({ ...reportForm, description: e.target.value })}
                        />
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                          <Label>Format</Label>
                          <Select
                            value={reportForm.format}
                            onValueChange={(value) => setReportForm({ ...reportForm, format: value })}
                          >
                            <SelectTrigger>
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="pdf">PDF</SelectItem>
                              <SelectItem value="excel">Excel</SelectItem>
                              <SelectItem value="csv">CSV</SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                        <div className="space-y-2">
                          <Label>Date Range</Label>
                          <Select
                            value={reportForm.dateRange}
                            onValueChange={(value) => setReportForm({ ...reportForm, dateRange: value })}
                          >
                            <SelectTrigger>
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="7">Last 7 days</SelectItem>
                              <SelectItem value="30">Last 30 days</SelectItem>
                              <SelectItem value="90">Last 90 days</SelectItem>
                              <SelectItem value="365">Last 12 months</SelectItem>
                              <SelectItem value="custom">Custom range</SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                      </div>

                      {reportForm.dateRange === 'custom' && (
                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-2">
                            <Label>Start Date</Label>
                            <Input
                              type="date"
                              value={reportForm.customStartDate}
                              onChange={(e) => setReportForm({ ...reportForm, customStartDate: e.target.value })}
                            />
                          </div>
                          <div className="space-y-2">
                            <Label>End Date</Label>
                            <Input
                              type="date"
                              value={reportForm.customEndDate}
                              onChange={(e) => setReportForm({ ...reportForm, customEndDate: e.target.value })}
                            />
                          </div>
                        </div>
                      )}

                      {selectedTemplate === 'custom' && (
                        <div className="space-y-2">
                          <Label>Select Metrics</Label>
                          <div className="border rounded-lg p-4 max-h-[200px] overflow-y-auto">
                            {['Properties', 'Financial', 'Activity', 'Maintenance'].map((category) => (
                              <div key={category} className="mb-4">
                                <p className="text-sm font-medium text-gray-500 mb-2">{category}</p>
                                <div className="space-y-2">
                                  {availableMetrics
                                    .filter(m => m.category === category)
                                    .map((metric) => (
                                      <div key={metric.id} className="flex items-center space-x-2">
                                        <Checkbox
                                          id={metric.id}
                                          checked={reportForm.selectedMetrics.includes(metric.id)}
                                          onCheckedChange={() => toggleMetric(metric.id)}
                                        />
                                        <Label htmlFor={metric.id} className="text-sm">
                                          {metric.name}
                                        </Label>
                                      </div>
                                    ))}
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      <div className="border-t pt-4">
                        <div className="flex items-center justify-between mb-4">
                          <div>
                            <p className="font-medium">Schedule Report</p>
                            <p className="text-sm text-gray-500">Automatically generate and send</p>
                          </div>
                          <Switch
                            checked={reportForm.isScheduled}
                            onCheckedChange={(checked) => setReportForm({ ...reportForm, isScheduled: checked })}
                          />
                        </div>

                        {reportForm.isScheduled && (
                          <div className="space-y-4">
                            <div className="space-y-2">
                              <Label>Frequency</Label>
                              <Select
                                value={reportForm.frequency}
                                onValueChange={(value) => setReportForm({ ...reportForm, frequency: value })}
                              >
                                <SelectTrigger>
                                  <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                  <SelectItem value="daily">Daily</SelectItem>
                                  <SelectItem value="weekly">Weekly</SelectItem>
                                  <SelectItem value="monthly">Monthly</SelectItem>
                                </SelectContent>
                              </Select>
                            </div>
                            <div className="space-y-2">
                              <Label>Recipients (comma-separated emails)</Label>
                              <Input
                                placeholder="email1@example.com, email2@example.com"
                                value={reportForm.recipients}
                                onChange={(e) => setReportForm({ ...reportForm, recipients: e.target.value })}
                              />
                            </div>
                          </div>
                        )}
                      </div>
                    </div>
                  )}

                  {selectedTemplate && (
                    <DialogFooter>
                      <Button variant="outline" onClick={() => setShowCreateDialog(false)}>
                        Cancel
                      </Button>
                      <Button onClick={handleCreateReport}>
                        Create Report
                      </Button>
                    </DialogFooter>
                  )}
                </DialogContent>
              </Dialog>
            </div>
          </div>
        </div>
      </header>

      <div className="p-6">
        {/* Stats */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <Card>
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-600">Saved Reports</p>
                  <p className="text-2xl font-bold">12</p>
                </div>
                <FileText className="h-8 w-8 text-blue-500" />
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-600">Scheduled</p>
                  <p className="text-2xl font-bold">8</p>
                </div>
                <Calendar className="h-8 w-8 text-green-500" />
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-600">Generated This Month</p>
                  <p className="text-2xl font-bold">24</p>
                </div>
                <Download className="h-8 w-8 text-purple-500" />
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-600">Next Scheduled</p>
                  <p className="text-2xl font-bold">2h</p>
                </div>
                <Clock className="h-8 w-8 text-yellow-500" />
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Main Content */}
        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="mb-4">
            <TabsTrigger value="reports">
              <FileText className="h-4 w-4 mr-2" />
              My Reports
            </TabsTrigger>
            <TabsTrigger value="templates">
              <Copy className="h-4 w-4 mr-2" />
              Templates
            </TabsTrigger>
            <TabsTrigger value="history">
              <Clock className="h-4 w-4 mr-2" />
              History
            </TabsTrigger>
          </TabsList>

          {/* My Reports Tab */}
          <TabsContent value="reports">
            <Card>
              <CardHeader>
                <CardTitle>Saved Reports</CardTitle>
                <CardDescription>Your configured reports and schedules</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {mockReports.map((report) => (
                    <div key={report.id} className="border rounded-lg p-4">
                      <div className="flex items-start justify-between mb-3">
                        <div>
                          <div className="flex items-center space-x-2">
                            <h3 className="font-semibold">{report.name}</h3>
                            <Badge variant={report.format === 'pdf' ? 'default' : 'secondary'}>
                              {report.format.toUpperCase()}
                            </Badge>
                          </div>
                          <p className="text-sm text-gray-500 mt-1">{report.description}</p>
                        </div>
                        <div className="flex items-center space-x-2">
                          <Button variant="outline" size="sm" onClick={() => handleGenerateReport(report)}>
                            <Download className="h-4 w-4 mr-2" />
                            Download
                          </Button>
                          <Button variant="ghost" size="icon">
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button variant="ghost" size="icon">
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>

                      <div className="flex items-center justify-between text-sm">
                        <div className="flex items-center space-x-4">
                          {report.isScheduled ? (
                            <>
                              <span className="flex items-center text-green-600">
                                <Play className="h-3 w-3 mr-1" />
                                Scheduled ({report.frequency})
                              </span>
                              <span className="text-gray-500">
                                Next: {report.nextRunAt ? formatDate(report.nextRunAt) : 'N/A'}
                              </span>
                            </>
                          ) : (
                            <span className="flex items-center text-gray-500">
                              <Pause className="h-3 w-3 mr-1" />
                              Not scheduled
                            </span>
                          )}
                        </div>
                        <span className="text-gray-500">
                          Last run: {formatDate(report.lastRunAt)}
                        </span>
                      </div>

                      {report.isScheduled && report.recipients.length > 0 && (
                        <div className="mt-3 pt-3 border-t">
                          <div className="flex items-center text-sm text-gray-500">
                            <Mail className="h-4 w-4 mr-2" />
                            Recipients: {report.recipients.join(', ')}
                          </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* Templates Tab */}
          <TabsContent value="templates">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {reportTemplates.map((template) => {
                const IconComponent = template.icon;
                return (
                  <Card key={template.id} className="hover:shadow-md transition-shadow">
                    <CardContent className="p-6">
                      <div className="flex items-center space-x-3 mb-3">
                        <div className="p-2 bg-gray-100 rounded-lg">
                          <IconComponent className="h-6 w-6 text-gray-600" />
                        </div>
                        <h3 className="font-semibold">{template.name}</h3>
                      </div>
                      <p className="text-sm text-gray-500 mb-4">{template.description}</p>
                      {template.metrics.length > 0 && (
                        <div className="mb-4">
                          <p className="text-xs font-medium text-gray-500 mb-2">Includes:</p>
                          <div className="flex flex-wrap gap-1">
                            {template.metrics.slice(0, 3).map((metric) => (
                              <Badge key={metric} variant="outline" className="text-xs">
                                {metric}
                              </Badge>
                            ))}
                            {template.metrics.length > 3 && (
                              <Badge variant="outline" className="text-xs">
                                +{template.metrics.length - 3} more
                              </Badge>
                            )}
                          </div>
                        </div>
                      )}
                      <Button
                        className="w-full"
                        variant="outline"
                        onClick={() => {
                          setSelectedTemplate(template.id);
                          setReportForm({ ...reportForm, reportType: template.id });
                          setShowCreateDialog(true);
                        }}
                      >
                        Use Template
                      </Button>
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          </TabsContent>

          {/* History Tab */}
          <TabsContent value="history">
            <Card>
              <CardHeader>
                <CardTitle>Report History</CardTitle>
                <CardDescription>Previously generated reports</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead className="bg-gray-50 border-b">
                      <tr>
                        <th className="text-left p-3 font-medium">Report</th>
                        <th className="text-left p-3 font-medium">Generated</th>
                        <th className="text-left p-3 font-medium">Format</th>
                        <th className="text-left p-3 font-medium">Status</th>
                        <th className="text-left p-3 font-medium">Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {[
                        { name: 'Monthly Property Performance', date: new Date(Date.now() - 1000 * 60 * 60 * 24 * 2), format: 'pdf', status: 'completed' },
                        { name: 'Agent Performance Report', date: new Date(Date.now() - 1000 * 60 * 60 * 24 * 3), format: 'excel', status: 'completed' },
                        { name: 'Financial Summary', date: new Date(Date.now() - 1000 * 60 * 60 * 24 * 5), format: 'pdf', status: 'completed' },
                        { name: 'Maintenance Report', date: new Date(Date.now() - 1000 * 60 * 60 * 24 * 7), format: 'pdf', status: 'completed' },
                        { name: 'Marketing Report', date: new Date(Date.now() - 1000 * 60 * 60 * 24 * 10), format: 'excel', status: 'completed' },
                      ].map((item, index) => (
                        <tr key={index} className="border-b hover:bg-gray-50">
                          <td className="p-3 font-medium">{item.name}</td>
                          <td className="p-3">{formatDate(item.date)}</td>
                          <td className="p-3">
                            <Badge variant="outline">
                              {item.format === 'pdf' ? (
                                <><File className="h-3 w-3 mr-1" /> PDF</>
                              ) : (
                                <><FileSpreadsheet className="h-3 w-3 mr-1" /> Excel</>
                              )}
                            </Badge>
                          </td>
                          <td className="p-3">
                            <Badge className="bg-green-100 text-green-800">
                              {item.status}
                            </Badge>
                          </td>
                          <td className="p-3">
                            <Button variant="ghost" size="sm">
                              <Download className="h-4 w-4 mr-2" />
                              Download
                            </Button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

server/agents/SupervisorAgent.ts.content:
/**
 * Supervisor Agent
 * The master agent that oversees all operations, routes tasks, and makes high-level decisions
 */

import { BaseAgent } from './BaseAgent';
import {
  AgentType,
  AgentConfig,
  AgentTask,
  AgentDecision,
  TaskContext,
  IncomingMessage,
  MessageType,
  RoutingDecision,
  TaskPriority,
  TaskType,
  TaskStatus,
} from './types';
import { openaiClient, isOpenAIConfigured } from '../lib/openaiClient';

const openai = openaiClient;

export class SupervisorAgent extends BaseAgent {
  private agentRegistry: Map<AgentType, BaseAgent> = new Map();

  constructor() {
    super({
      id: 'supervisor',
      name: 'Supervisor Agent',
      description: 'Oversees all business operations, routes tasks to specialist agents, monitors performance, and makes high-level decisions',
      enabled: true,
      handlesMessageTypes: ['inquiry', 'viewing_request', 'offer', 'complaint', 'maintenance_request', 'contract_request', 'valuation_request', 'general', 'lead', 'follow_up'],
      handlesTaskTypes: ['classify_message', 'escalate_to_human', 'general_response'],
      communicationChannels: ['email', 'whatsapp', 'sms', 'phone', 'post', 'social_media'],
      personality: 'Professional business manager with deep knowledge of estate agency operations',
      tone: 'professional',
      language: 'en-GB',
      workingHours: { start: '00:00', end: '23:59' }, // Always on
      workingDays: ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'],
      responseDelaySeconds: 0,
      maxConcurrentTasks: 100,
    });
  }

  /**
   * Register a specialist agent
   */
  registerAgent(agent: BaseAgent): void {
    this.agentRegistry.set(agent.getConfig().id, agent);
    console.log(`[Supervisor] Registered agent: ${agent.getConfig().name}`);
  }

  /**
   * Get all registered agents
   */
  getRegisteredAgents(): Map<AgentType, BaseAgent> {
    return this.agentRegistry;
  }

  /**
   * Classify an incoming message and determine routing
   */
  async classifyMessage(message: IncomingMessage): Promise<RoutingDecision> {
    const prompt = `Analyze this incoming message and determine:
1. The type of message (inquiry, viewing_request, offer, complaint, maintenance_request, contract_request, valuation_request, general, lead, follow_up)
2. The most appropriate agent to handle it:
   - sales: Property sales, valuations, buyer inquiries, offers on sale properties
   - rental: Rental inquiries, tenant matching, viewing scheduling for rentals
   - maintenance: Repair requests, property issues, contractor coordination
   - office_admin: Contract management, general admin, document handling
   - lead_gen_sales: New vendor leads, valuation requests for selling
   - lead_gen_rentals: New landlord leads, rental valuation requests
   - marketing: Social media, marketing campaigns, content requests
3. Priority level (urgent, high, medium, low)

Message Details:
Channel: ${message.channel}
From: ${message.fromName || message.from}
Subject: ${message.subject || 'N/A'}
Content: ${message.body}

Respond with a JSON object:
{
  "messageType": "the message type",
  "assignTo": "agent type",
  "priority": "priority level",
  "reasoning": "brief explanation",
  "confidence": 0.0-1.0,
  "suggestedTaskType": "the task type to create"
}`;

    try {
      const response = await openai.chat.completions.create({
        model: 'gpt-4-turbo-preview',
        messages: [
          {
            role: 'system',
            content: 'You are an expert message classifier for a London estate agency. Analyze messages and route them to the appropriate specialist agent.',
          },
          { role: 'user', content: prompt },
        ],
        response_format: { type: 'json_object' },
        temperature: 0.3,
        max_tokens: 500,
      });

      const content = response.choices[0]?.message?.content;
      if (!content) {
        throw new Error('No classification response');
      }

      const classification = JSON.parse(content) as RoutingDecision;
      console.log(`[Supervisor] Classified message as ${classification.messageType} -> ${classification.assignTo} (${classification.confidence * 100}% confidence)`);

      return classification;
    } catch (error) {
      console.error('[Supervisor] Classification error:', error);

      // Default to office admin for unclassifiable messages
      return {
        messageType: 'general',
        assignTo: 'office_admin',
        priority: 'medium',
        reasoning: 'Unable to classify automatically, routing to office admin',
        confidence: 0.3,
        suggestedTaskType: 'general_response',
      };
    }
  }

  /**
   * Create a task from an incoming message
   */
  async createTaskFromMessage(message: IncomingMessage, routing: RoutingDecision): Promise<AgentTask> {
    const task: AgentTask = {
      id: `task_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: routing.suggestedTaskType as TaskType,
      title: this.generateTaskTitle(message, routing),
      description: message.body.substring(0, 500),
      priority: routing.priority,
      status: 'pending',
      assignedTo: routing.assignTo,
      assignedBy: 'supervisor',
      createdAt: new Date(),
      updatedAt: new Date(),
      propertyId: message.propertyId,
      contactId: message.contactId,
      conversationId: message.conversationId,
      input: {
        message,
        routing,
        channel: message.channel,
        from: message.from,
        fromName: message.fromName,
        subject: message.subject,
        body: message.body,
      },
      attempts: 0,
      maxAttempts: 3,
    };

    return task;
  }

  /**
   * Generate a task title from message
   */
  private generateTaskTitle(message: IncomingMessage, routing: RoutingDecision): string {
    const typeLabels: Record<MessageType, string> = {
      inquiry: 'Property Inquiry',
      viewing_request: 'Viewing Request',
      offer: 'Offer Received',
      complaint: 'Complaint',
      maintenance_request: 'Maintenance Request',
      contract_request: 'Contract Request',
      valuation_request: 'Valuation Request',
      general: 'General Inquiry',
      lead: 'New Lead',
      follow_up: 'Follow Up Required',
    };

    const label = typeLabels[routing.messageType] || 'Task';
    const from = message.fromName || message.from;
    return `${label} from ${from}`.substring(0, 100);
  }

  /**
   * Route a task to the appropriate agent
   */
  async routeTask(task: AgentTask): Promise<AgentDecision> {
    const agent = this.agentRegistry.get(task.assignedTo);

    if (!agent) {
      console.warn(`[Supervisor] No agent found for type: ${task.assignedTo}, handling directly`);
      return this.processTask(task);
    }

    if (!agent.isActive()) {
      console.log(`[Supervisor] Agent ${task.assignedTo} is not active, queuing task`);
      return {
        action: 'wait',
        reasoning: `Agent ${task.assignedTo} is currently offline. Task queued for processing.`,
        confidence: 1.0,
        nextSteps: ['Wait for agent to become active', 'Process when available'],
      };
    }

    // Delegate to the specialist agent
    console.log(`[Supervisor] Routing task ${task.id} to ${task.assignedTo}`);
    return agent.processTask(task);
  }

  /**
   * Process incoming message - main entry point
   */
  async processIncomingMessage(message: IncomingMessage): Promise<{
    task: AgentTask;
    decision: AgentDecision;
    routing: RoutingDecision;
  }> {
    // Step 1: Classify the message
    const routing = await this.classifyMessage(message);

    // Step 2: Create a task
    const task = await this.createTaskFromMessage(message, routing);

    // Step 3: Route to appropriate agent
    const decision = await this.routeTask(task);

    // Step 4: Update task status based on decision
    task.status = this.getTaskStatusFromDecision(decision);
    task.output = {
      decision,
      routing,
    };

    return { task, decision, routing };
  }

  /**
   * Get task status from decision
   */
  private getTaskStatusFromDecision(decision: AgentDecision): TaskStatus {
    switch (decision.action) {
      case 'complete':
        return 'completed';
      case 'escalate':
        return 'escalated';
      case 'wait':
        return 'awaiting_response';
      case 'delegate':
        return 'assigned';
      default:
        return 'in_progress';
    }
  }

  /**
   * Monitor agent performance
   */
  getAgentPerformance(): Record<AgentType, {
    name: string;
    enabled: boolean;
    isActive: boolean;
    metrics: ReturnType<BaseAgent['getMetrics']>;
  }> {
    const performance: Record<string, any> = {};

    for (const [type, agent] of this.agentRegistry) {
      const config = agent.getConfig();
      performance[type] = {
        name: config.name,
        enabled: config.enabled,
        isActive: agent.isActive(),
        metrics: agent.getMetrics(),
      };
    }

    return performance as any;
  }

  /**
   * Handle escalation from other agents
   */
  async handleEscalation(task: AgentTask, reason: string): Promise<AgentDecision> {
    console.log(`[Supervisor] Handling escalation for task ${task.id}: ${reason}`);

    // Try to reassign to a different agent or escalate to human
    const alternativeAgents = this.findAlternativeAgents(task);

    if (alternativeAgents.length > 0) {
      const newAgent = alternativeAgents[0];
      console.log(`[Supervisor] Reassigning to ${newAgent}`);

      task.assignedTo = newAgent;
      task.attempts++;
      task.updatedAt = new Date();

      return this.routeTask(task);
    }

    // No alternative agents, escalate to human
    return {
      action: 'escalate',
      reasoning: `Task requires human intervention: ${reason}`,
      confidence: 1.0,
      escalate: true,
      escalationReason: reason,
      nextSteps: ['Notify human staff', 'Add to priority queue'],
    };
  }

  /**
   * Find alternative agents that could handle a task
   */
  private findAlternativeAgents(task: AgentTask): AgentType[] {
    const alternatives: AgentType[] = [];

    for (const [type, agent] of this.agentRegistry) {
      if (type !== task.assignedTo && agent.canHandle(task.type) && agent.isActive()) {
        alternatives.push(type);
      }
    }

    return alternatives;
  }

  /**
   * Build user prompt for task processing
   */
  protected buildUserPrompt(task: AgentTask, context: TaskContext): string {
    return `
Task ID: ${task.id}
Type: ${task.type}
Priority: ${task.priority}
Description: ${task.description}

Input Data:
${JSON.stringify(task.input, null, 2)}

Context:
${context.contact ? `Contact: ${context.contact.name} (${context.contact.type})` : 'No contact info'}
${context.property ? `Property: ${context.property.address}` : 'No property info'}
${context.conversationHistory?.length ? `Conversation History: ${context.conversationHistory.length} messages` : 'No history'}

As the Supervisor Agent, determine the best course of action for this task.
`;
  }

  /**
   * Get system status summary
   */
  getSystemStatus(): {
    totalAgents: number;
    activeAgents: number;
    totalTasksProcessed: number;
    averageResponseTime: number;
    overallSuccessRate: number;
  } {
    const agentPerformance = this.getAgentPerformance();
    const agentTypes = Object.keys(agentPerformance);

    let totalTasks = 0;
    let totalTime = 0;
    let totalSuccess = 0;
    let activeCount = 0;

    for (const type of agentTypes) {
      const perf = agentPerformance[type as AgentType];
      if (perf.isActive) activeCount++;
      totalTasks += perf.metrics.tasksCompleted + perf.metrics.tasksFailed;
      totalTime += perf.metrics.averageResponseTime * (perf.metrics.tasksCompleted + perf.metrics.tasksFailed);
      totalSuccess += perf.metrics.tasksCompleted;
    }

    return {
      totalAgents: agentTypes.length,
      activeAgents: activeCount,
      totalTasksProcessed: totalTasks,
      averageResponseTime: totalTasks > 0 ? totalTime / totalTasks : 0,
      overallSuccessRate: totalTasks > 0 ? (totalSuccess / totalTasks) * 100 : 0,
    };
  }
}

// Export singleton instance
export const supervisorAgent = new SupervisorAgent();

