  address: string;
  postcode: string;
  price: number;
  propertyType: string;
  bedrooms: number;
  bathrooms: number;
  daysOnMarket: number;
  listedDate: string;
  agentName: string;
  agentPhone?: string;
  lastPriceChange?: string;
  priceHistory: { date: string; price: number }[];
  status: 'new' | 'contacted' | 'responded' | 'declined' | 'converted';
  contactAttempts: number;
