  notes?: string;
  estimatedMarketValue: number;
  cashOfferPrice: number;
}

interface CashOffer {
  id: number;
  listingId: number;
  address: string;
  postcode: string;
  marketValue: number;
  offerPrice: number;
  discountPercent: number;
  status: 'draft' | 'sent' | 'viewed' | 'accepted' | 'declined' | 'expired';
  sentDate?: string;
  sentVia: 'post' | 'email' | 'whatsapp';
  responseDate?: string;
  expiryDate: string;
  letterTemplate: string;
}

interface MonitorSettings {
  enabled: boolean;
  portals: string[];
  postcodeAreas: string[];
  minDaysOnMarket: number;
  maxDaysOnMarket: number;
  minPrice: number;
  maxPrice: number;
  propertyTypes: string[];
  autoContact: boolean;
  contactMethod: 'post' | 'email' | 'both';
  cashOfferPercent: number;
  completionDays: number;
  scanFrequency: 'hourly' | 'daily' | 'weekly';
  lastScanTime?: string;
}

// Mock data for stale listings
const MOCK_STALE_LISTINGS: StaleListing[] = [
  {
    id: 1,
    portal: 'zoopla',
    portalListingId: 'ZPL123456',
    address: '45 Maida Vale, London',
    postcode: 'W9 1QE',
