                <FormItem className="flex items-start gap-2 pt-3">
                  <FormControl>
                    <Checkbox
                      checked={field.value}
                      onCheckedChange={field.onChange}
                      className="mt-[0.3rem] border-neutral-300 data-[state=checked]:bg-[#0E6BFF] data-[state=checked]:border-[#0E6BFF]"
