import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import { useToast } from '@/hooks/use-toast';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Loader2, Sparkles } from 'lucide-react';
import { apiRequest } from '@/lib/queryClient';

// Define a simple schema with just what's needed for UK HPI
const hpiFormSchema = z.object({
  addressLine1: z.string().min(5, "Please enter the first line of your address"),
  postcode: z.string()
    .min(5, "Please enter a valid UK postcode")
    .refine(
      (val) => /^[A-Z]{1,2}[0-9][A-Z0-9]?[0-9][A-Z]{2}$/i.test(val.replace(/\s+/g, '')),
      { message: "Please enter a valid UK postcode format" }
    ),
  propertyType: z.enum(["detached", "semi-detached", "terraced", "flat", "bungalow", "other"]),
  bedrooms: z.enum(["1", "2", "3", "4", "5+"]),
  email: z.string().email("Please enter a valid email address"),
  phone: z.string().min(10, "Please enter a valid phone number"),
});

type HpiFormData = z.infer<typeof hpiFormSchema>;

const propertyTypeOptions = [
  { value: "detached", label: "Detached" },
  { value: "semi-detached", label: "Semi-Detached" },
  { value: "terraced", label: "Terraced" },
  { value: "flat", label: "Flat/Apartment" },
  { value: "bungalow", label: "Bungalow" },
  { value: "other", label: "Other" }
];

const bedroomOptions = [
  { value: "1", label: "1" },
  { value: "2", label: "2" },
  { value: "3", label: "3" },
  { value: "4", label: "4" },
  { value: "5+", label: "5+" }
];

interface SimpleHpiFormProps {
  onSubmit: (data: HpiFormData) => Promise<void>;
  isSubmitting?: boolean;
}

const SimpleHpiForm = ({ onSubmit, isSubmitting = false }: SimpleHpiFormProps) => {
  const { toast } = useToast();

  const form = useForm<HpiFormData>({
    resolver: zodResolver(hpiFormSchema),
    defaultValues: {
      addressLine1: '',
      postcode: '',
      propertyType: undefined,
      bedrooms: undefined,
      email: '',
      phone: ''
    }
  });

  // Function to validate and format UK postcode
  const formatPostcode = (value: string) => {
    if (!value) return value;

    // Clean and format the postcode
    let cleanPostcode = value.replace(/\s+/g, '').toUpperCase();

    // Format with a space in the right position
    return cleanPostcode.replace(/^(.+?)([0-9][A-Z]{2})$/, '$1 $2');
  };

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6 p-6 bg-white rounded-lg shadow-md border border-[#0E6BFF]">
        <div className="text-center mb-4">
          <h2 className="text-2xl font-bold text-[#0E6BFF]">Free Property Valuation</h2>
        </div>

        <div className="space-y-4">
          <FormField
            control={form.control}
            name="addressLine1"
            render={({ field }) => (
              <FormItem>
                <FormLabel className="font-medium">Address Line 1 *</FormLabel>
                <FormControl>
                  <Input 
                    placeholder="e.g. 123 Main Street" 
                    className="border-gray-300" 
                    {...field} 
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="postcode"
            render={({ field }) => (
              <FormItem>
                <FormLabel className="font-medium">Postcode *</FormLabel>
                <FormControl>
                  <Input 
                    placeholder="e.g. SW1A 1AA" 
                    className="border-gray-300" 
                    {...field} 
                    onBlur={(e) => {
                      // Format postcode on blur
                      const formatted = formatPostcode(e.target.value);
                      if (formatted !== e.target.value) {
                        field.onChange(formatted);
                      }
                      // Continue with default onBlur behavior
                      field.onBlur();
                    }}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <FormField
              control={form.control}
              name="propertyType"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="font-medium">Property Type *</FormLabel>
                  <Select onValueChange={field.onChange} defaultValue={field.value}>
                    <FormControl>
                      <SelectTrigger className="border-gray-300">
                        <SelectValue placeholder="Select property type" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      {propertyTypeOptions.map(option => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="bedrooms"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="font-medium">Number of Bedrooms *</FormLabel>
                  <Select onValueChange={field.onChange} defaultValue={field.value}>
                    <FormControl>
                      <SelectTrigger className="border-gray-300">
                        <SelectValue placeholder="Select bedrooms" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      {bedroomOptions.map(option => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label} {parseInt(option.label) === 1 ? "Bedroom" : "Bedrooms"}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <FormField
              control={form.control}
              name="email"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="font-medium">Email Address *</FormLabel>
                  <FormControl>
                    <Input 
                      type="email"
                      placeholder="your.email@example.com" 
                      className="border-gray-300" 
                      {...field} 
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="phone"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="font-medium">Phone Number *</FormLabel>
                  <FormControl>
                    <Input 
                      placeholder="07123 456789" 
                      className="border-gray-300" 
                      {...field} 
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </div>
        </div>

        <Button 
          type="submit" 
          className="w-full bg-[#0E6BFF] hover:bg-[#0E6BFF]/90 py-6 text-lg"
          disabled={isSubmitting}
        >
          {isSubmitting ? (
            <>
              <Loader2 className="mr-2 h-4 w-4 animate-spin" /> Processing...
            </>
          ) : (
            <>
              Get My Free Valuation <Sparkles className="ml-2 h-4 w-4" />
            </>
          )}
        </Button>


      </form>
    </Form>
  );
};

export default SimpleHpiForm;

scripts/parse-rental-inventory.js.content:
import XLSX from 'xlsx';
import path from 'path';

// Path to the Excel file
const filePath = 'C:\\Users\\ziaa\\Dropbox\\ZA\\DOWNLOADS\\BUSINESS\\JOHN BARCLAY\\Documentation\\rental Inventory.xlsx';

try {
  // Read the workbook
  const workbook = XLSX.readFile(filePath);

  console.log('=== WORKBOOK INFO ===');
  console.log('Sheet names:', workbook.SheetNames);

  // Process each sheet
  workbook.SheetNames.forEach(sheetName => {
    console.log(`\n=== SHEET: ${sheetName} ===`);
    const sheet = workbook.Sheets[sheetName];

    // Convert to JSON to see the data
    const data = XLSX.utils.sheet_to_json(sheet, { header: 1 });

    if (data.length > 0) {
      console.log('\nColumn Headers (Row 1):');
      const headers = data[0];
      headers.forEach((header, index) => {
        console.log(`  ${index + 1}. ${header}`);
      });

      console.log(`\nTotal rows: ${data.length}`);

      // Show first few rows of data
      console.log('\nFirst 3 data rows:');
      for (let i = 1; i < Math.min(4, data.length); i++) {
        console.log(`\nRow ${i + 1}:`);
        data[i].forEach((cell, index) => {
          if (cell !== undefined && cell !== null && cell !== '') {
            console.log(`  ${headers[index] || `Column ${index + 1}`}: ${cell}`);
          }
        });
      }
    } else {
      console.log('Sheet is empty');
    }
  });

  // Output full JSON for processing
  console.log('\n\n=== FULL JSON DATA ===');
  const mainSheet = workbook.Sheets[workbook.SheetNames[0]];
  const jsonData = XLSX.utils.sheet_to_json(mainSheet);
  console.log(JSON.stringify(jsonData, null, 2));

} catch (error) {
  console.error('Error reading Excel file:', error.message);
}

investigate-text-cutoff.js.content:
import { chromium } from 'playwright';

async function investigateTextCutoff() {
  const browser = await chromium.launch({
    headless: false,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  const page = await browser.newPage();
  await page.setViewportSize({ width: 1920, height: 1080 });

  try {
    console.log('Navigating to http://localhost:5173/...');
    await page.goto('http://localhost:5173/', {
      waitUntil: 'networkidle',
      timeout: 10000
    });

    // Wait for content to load
    await page.waitForTimeout(3000);

    // Navigate to history section
    console.log('\n=== NAVIGATING TO HISTORY SECTION ===');
    await page.evaluate(() => {
      window.scrollTo(0, 1200); // Scroll to history section
    });

    await page.waitForTimeout(2000);

    // Take screenshot of history section
    await page.screenshot({
      path: 'history-section-text-cutoff.png',
      fullPage: false
    });
    console.log('History section screenshot saved');

    // Analyze text elements and their containers
    console.log('\n=== ANALYZING TEXT ELEMENTS IN HISTORY SECTION ===');

    const textAnalysis = await page.evaluate(() => {
      const historySection = document.querySelector('section[style*="z-index: 20"]') ||
                           Array.from(document.querySelectorAll('section')).find(s =>
                             s.textContent.includes('PRIME') || s.textContent.includes('OUR STORY')
                           );

      if (!historySection) {
        return { found: false };
      }

      const results = {
        found: true,
        elements: []
      };

      // Find all text containers in the history section
      const textContainers = historySection.querySelectorAll('div, p, h1, h2, h3, h4');

      textContainers.forEach((element, index) => {
        const rect = element.getBoundingClientRect();
        const computedStyle = window.getComputedStyle(element);
        const text = element.textContent?.trim();

        if (text && text.length > 10) { // Only analyze elements with meaningful text
          const isCutOff = rect.width > 0 && (
            element.scrollWidth > element.clientWidth ||
            element.scrollHeight > element.clientHeight ||
            rect.right > window.innerWidth ||
            rect.left < 0
          );

          results.elements.push({
            index,
            tagName: element.tagName,
            className: element.className,
            text: text.substring(0, 100) + (text.length > 100 ? '...' : ''),
            width: rect.width,
            height: rect.height,
            left: rect.left,
            right: rect.right,
            clientWidth: element.clientWidth,
            scrollWidth: element.scrollWidth,
            clientHeight: element.clientHeight,
            scrollHeight: element.scrollHeight,
            isCutOff,
            maxWidth: computedStyle.maxWidth,
            overflow: computedStyle.overflow,
            overflowX: computedStyle.overflowX,
            padding: computedStyle.padding,
            margin: computedStyle.margin
          });
        }
      });

      return results;
    });

    if (textAnalysis.found) {
      console.log('Text Elements Analysis:');
      textAnalysis.elements.forEach((element, i) => {
        console.log(`\nElement ${i} (${element.tagName}):`);
        console.log(`  Class: ${element.className}`);
        console.log(`  Text: ${element.text}`);
        console.log(`  Dimensions: ${element.width}x${element.height}`);
        console.log(`  Position: left=${element.left}, right=${element.right}`);
        console.log(`  Scroll vs Client: ${element.scrollWidth}x${element.scrollHeight} vs ${element.clientWidth}x${element.clientHeight}`);
        console.log(`  Cut Off: ${element.isCutOff}`);
        console.log(`  Max Width: ${element.maxWidth}`);
        console.log(`  Overflow: ${element.overflow}, OverflowX: ${element.overflowX}`);

        if (element.isCutOff) {
          console.log(`  ⚠️  TEXT IS CUT OFF!`);
        }
      });

      // Focus on cut-off elements
      const cutOffElements = textAnalysis.elements.filter(e => e.isCutOff);
      if (cutOffElements.length > 0) {
        console.log(`\n=== ${cutOffElements.length} ELEMENTS WITH TEXT CUT-OFF FOUND ===`);
        cutOffElements.forEach(element => {
          console.log(`- ${element.tagName}.${element.className}: "${element.text}"`);
        });
      } else {
        console.log('\n✅ No text cut-off detected');
      }
    } else {
      console.log('❌ Could not find history section');
    }

    // Check specific column widths
    console.log('\n=== CHECKING COLUMN WIDTHS ===');
    const columnAnalysis = await page.evaluate(() => {
      const columns = {
        topLeft: document.querySelector('.w-1\\/2.h-full.bg-black'),
        topRight: document.querySelector('.h-1\\/2 .w-1\\/2:nth-child(2)'),
        bottomLeft: document.querySelector('.h-1\\/2:nth-child(2) .w-1\\/2:first-child'),
        bottomRight: document.querySelector('.h-1\\/2:nth-child(2) .w-1\\/2:nth-child(2)')
      };

      const results = {};

      Object.entries(columns).forEach(([name, element]) => {
        if (element) {
          const rect = element.getBoundingClientRect();
          const computedStyle = window.getComputedStyle(element);
          results[name] = {
            width: rect.width,
            height: rect.height,
            padding: computedStyle.padding,
            maxWidth: computedStyle.maxWidth,
            className: element.className
          };
        } else {
          results[name] = { found: false };
        }
      });

      return results;
    });

    console.log('Column Analysis:');
    Object.entries(columnAnalysis).forEach(([name, data]) => {
      if (data.found !== false) {
        console.log(`\n${name}:`);
        console.log(`  Width: ${data.width}px`);
        console.log(`  Height: ${data.height}px`);
        console.log(`  Padding: ${data.padding}`);
        console.log(`  Max Width: ${data.maxWidth}`);
        console.log(`  Classes: ${data.className}`);
      } else {
        console.log(`\n${name}: Not found`);
      }
    });

    // Test horizontal scrolling area
    console.log('\n=== TESTING HORIZONTAL SCROLL CONTENT ===');
    await page.evaluate(() => {
      const scrollArea = document.querySelector('.overflow-x-auto');
      if (scrollArea) {
        scrollArea.scrollLeft = 300; // Scroll horizontally to see panels
      }
    });

    await page.waitForTimeout(1000);
    await page.screenshot({
      path: 'history-section-horizontal-scrolled.png',
      fullPage: false
    });
    console.log('Horizontal scrolled screenshot saved');

  } catch (error) {
    console.error('Error during investigation:', error.message);
  } finally {
    await browser.close();
  }
}

investigateTextCutoff();

