import { useState, useRef, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';
import { contactFormSchema, type ContactFormData } from '@shared/schema';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Button } from '@/components/ui/button';
import { Phone, Mail, MapPin, MessageCircle, ArrowRight } from 'lucide-react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const ContactSection = () => {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { toast } = useToast();

  // Animation refs
  const titleRef = useRef<HTMLDivElement>(null);
  const subtitleRef = useRef<HTMLDivElement>(null);
  const phoneRef = useRef<HTMLDivElement>(null);
  const emailRef = useRef<HTMLDivElement>(null);
  const locationRef = useRef<HTMLDivElement>(null);
  const whatsappRef = useRef<HTMLDivElement>(null);
  const hoursRef = useRef<HTMLDivElement>(null);
  const contactRefs = useRef<HTMLDivElement[]>([]);

  const form = useForm<ContactFormData>({
    resolver: zodResolver(contactFormSchema),
    defaultValues: {
      fullName: '',
      email: '',
      phone: '',
      message: ''
    }
  });

  useEffect(() => {
    // Initial state - hide all elements
    gsap.set([titleRef.current, subtitleRef.current, phoneRef.current, emailRef.current, locationRef.current, whatsappRef.current, hoursRef.current], {
      opacity: 0,
      y: 100,
      scale: 0.8
    });

    // Title animation
    gsap.to(titleRef.current, {
      opacity: 1,
      y: 0,
      scale: 1,
      duration: 1.5,
      ease: "power3.out",
      scrollTrigger: {
        trigger: titleRef.current,
        start: "top 80%",
        toggleActions: "play none none reverse"
      }
    });

    // Subtitle animation
    gsap.to(subtitleRef.current, {
      opacity: 1,
      y: 0,
      scale: 1,
      duration: 1.2,
      ease: "power3.out",
      delay: 0.3,
      scrollTrigger: {
        trigger: subtitleRef.current,
        start: "top 80%",
        toggleActions: "play none none reverse"
      }
    });

    // Contact items staggered animation
    const contactItems = [phoneRef.current, emailRef.current, locationRef.current];
    gsap.to(contactItems, {
      opacity: 1,
      y: 0,
      scale: 1,
      duration: 1,
      ease: "power3.out",
      stagger: 0.2,
      delay: 0.6,
      scrollTrigger: {
        trigger: phoneRef.current,
        start: "top 80%",
        toggleActions: "play none none reverse"
      }
    });

    // WhatsApp button animation
    gsap.to(whatsappRef.current, {
      opacity: 1,
      y: 0,
      scale: 1,
      duration: 1.5,
      ease: "elastic.out(1, 0.3)",
      delay: 1.2,
      scrollTrigger: {
        trigger: whatsappRef.current,
        start: "top 80%",
        toggleActions: "play none none reverse"
      }
    });

    // Working hours animation
    gsap.to(hoursRef.current, {
      opacity: 1,
      y: 0,
      scale: 1,
      duration: 1.2,
      ease: "power3.out",
      delay: 1.5,
      scrollTrigger: {
        trigger: hoursRef.current,
        start: "top 80%",
        toggleActions: "play none none reverse"
      }
    });

    // Removed floating and pulsing animations for a cleaner look

  }, []);

  const onSubmit = async (data: ContactFormData) => {
    setIsSubmitting(true);

    try {
      await apiRequest('POST', '/api/contacts', data);

      toast({
        title: "Message sent!",
        description: "Thank you for contacting us. We'll be in touch shortly.",
