    return `${cleanPostcode.substring(0, 2)} ${cleanPostcode.substring(2)}`;
  } else if (length === 6) {
    // For postcodes like AB9 9AA
    return `${cleanPostcode.substring(0, 3)} ${cleanPostcode.substring(3)}`;
  } else {
