import { useState, useEffect } from 'react';
import { MapPin } from 'lucide-react';

interface PropertyMapProps {
  address: string;
  postcode: string;
  width?: string;
  height?: string;
  zoom?: number;
  className?: string;
}

// UK postcode to approximate coordinates lookup
const postcodeCoordinates: { [key: string]: { lat: number; lng: number } } = {
  'W9': { lat: 51.5268, lng: -0.1858 },  // Maida Vale
  'W10': { lat: 51.5228, lng: -0.2154 }, // North Kensington
  'W11': { lat: 51.5118, lng: -0.2054 }, // Notting Hill
  'W2': { lat: 51.5154, lng: -0.1755 },  // Bayswater
  'NW6': { lat: 51.5479, lng: -0.1922 }, // Kilburn/Queens Park
  'NW10': { lat: 51.5347, lng: -0.2277 }, // Kensal Green/Harlesden
  'NW8': { lat: 51.5324, lng: -0.1698 }, // St John's Wood
  'SW1': { lat: 51.4975, lng: -0.1357 }, // Westminster
  'SW3': { lat: 51.4903, lng: -0.1678 }, // Chelsea
  'SW7': { lat: 51.4942, lng: -0.1778 }, // South Kensington
};

// Get coordinates from postcode
function getCoordinatesFromPostcode(postcode: string): { lat: number; lng: number } {
  const outwardCode = postcode.split(' ')[0].toUpperCase();
  return postcodeCoordinates[outwardCode] || { lat: 51.5074, lng: -0.1278 }; // Default to London center
}

// Generate static map URL using Mapbox
function generateMapUrl(lat: number, lng: number, width: number, height: number, zoom: number): string {
  const mapboxToken = 'pk.eyJ1IjoiYWZ6YWx6IiwiYSI6ImNtOTlzcG5iaTBjdHIya3NkYWcxc21wZHMifQ.HYl1dbN2OLp2GC1QHzqBcw';
  const marker = `pin-s+791E75(${lng},${lat})`;
  return `https://api.mapbox.com/styles/v1/mapbox/streets-v12/static/${marker}/${lng},${lat},${zoom},0/${width}x${height}@2x?access_token=${mapboxToken}`;
}

// Generate OpenStreetMap embed URL as fallback
function generateOSMUrl(lat: number, lng: number, zoom: number): string {
  return `https://www.openstreetmap.org/export/embed.html?bbox=${lng-0.01},${lat-0.01},${lng+0.01},${lat+0.01}&layer=mapnik&marker=${lat},${lng}`;
}

export function PropertyMap({
  address,
  postcode,
  width = '100%',
  height = '150px',
  zoom = 15,
  className = ''
}: PropertyMapProps) {
  const [mapUrl, setMapUrl] = useState<string>('');
  const [useIframe, setUseIframe] = useState(false);
  const [coordinates, setCoordinates] = useState<{ lat: number; lng: number } | null>(null);

  useEffect(() => {
    if (postcode) {
      const coords = getCoordinatesFromPostcode(postcode);
      setCoordinates(coords);

      // Generate static map URL
      const pixelWidth = parseInt(width) || 300;
      const pixelHeight = parseInt(height) || 150;
      setMapUrl(generateMapUrl(coords.lat, coords.lng, pixelWidth, pixelHeight, zoom));
    }
  }, [postcode, width, height, zoom]);

  if (!postcode || !coordinates) {
    return (
      <div
        className={`bg-gray-100 rounded-lg flex items-center justify-center ${className}`}
        style={{ width, height }}
      >
        <div className="text-center text-gray-400">
          <MapPin className="h-6 w-6 mx-auto mb-1" />
          <p className="text-xs">No location data</p>
        </div>
      </div>
    );
  }

  return (
    <div className={`relative overflow-hidden rounded-lg ${className}`} style={{ width, height }}>
      {useIframe ? (
        <iframe
          src={generateOSMUrl(coordinates.lat, coordinates.lng, zoom)}
          style={{ width: '100%', height: '100%', border: 0 }}
          title={`Map of ${address}`}
          loading="lazy"
        />
      ) : (
        <img
          src={mapUrl}
          alt={`Map of ${address}, ${postcode}`}
          className="w-full h-full object-cover"
          onError={() => setUseIframe(true)}
          loading="lazy"
        />
      )}

      {/* Address overlay */}
      <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/60 to-transparent p-2">
        <div className="flex items-center text-white text-xs">
          <MapPin className="h-3 w-3 mr-1 flex-shrink-0" />
          <span className="truncate">{postcode}</span>
        </div>
      </div>
    </div>
  );
}

// Mini map for property cards
export function PropertyMiniMap({
  postcode,
  className = ''
}: {
  postcode: string;
  className?: string;
}) {
  const coords = getCoordinatesFromPostcode(postcode);
  const mapboxToken = 'pk.eyJ1IjoiYWZ6YWx6IiwiYSI6ImNtOTlzcG5iaTBjdHIya3NkYWcxc21wZHMifQ.HYl1dbN2OLp2GC1QHzqBcw';

  if (!postcode) {
    return (
      <div className={`bg-gray-100 rounded flex items-center justify-center ${className}`}>
        <MapPin className="h-4 w-4 text-gray-400" />
      </div>
    );
  }

  const mapUrl = `https://api.mapbox.com/styles/v1/mapbox/streets-v12/static/pin-s+791E75(${coords.lng},${coords.lat})/${coords.lng},${coords.lat},13,0/80x80@2x?access_token=${mapboxToken}`;

  return (
    <img
      src={mapUrl}
      alt={`Map for ${postcode}`}
      className={`object-cover rounded ${className}`}
      loading="lazy"
      onError={(e) => {
        (e.target as HTMLImageElement).style.display = 'none';
      }}
    />
  );
}

export default PropertyMap;

