import { useState, useEffect, useRef } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Link, useLocation } from "wouter";
import { useMutation } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Loader2, Home, User, Shield, Users, Eye, EyeOff } from "lucide-react";
import heroLogo from "@/assets/john-barclay-hero-logo.png";
import gsap from "gsap";

const loginSchema = z.object({
  username: z.string().min(3, "Username must be at least 3 characters"),
  password: z.string().min(6, "Password must be at least 6 characters"),
});

const registerSchema = z.object({
  username: z.string().min(3, "Username must be at least 3 characters"),
  email: z.string().email("Invalid email address"),
  password: z.string().min(6, "Password must be at least 6 characters"),
  confirmPassword: z.string(),
  fullName: z.string().min(2, "Full name is required"),
  phone: z.string().optional(),
  role: z.enum(["user", "tenant", "landlord", "agent", "maintenance_staff", "admin"]).default("user"),
}).refine((data) => data.password === data.confirmPassword, {
  message: "Passwords don't match",
  path: ["confirmPassword"],
});

type LoginForm = z.infer<typeof loginSchema>;
type RegisterForm = z.infer<typeof registerSchema>;

export default function Login() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [activeTab, setActiveTab] = useState("login");
  const [showLoginPassword, setShowLoginPassword] = useState(false);
  const [showRegisterPassword, setShowRegisterPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const logoRef = useRef<HTMLImageElement>(null);
  const [mousePos, setMousePos] = useState({ x: 0.5, y: 0.5 });
  const [isVideoLoaded, setIsVideoLoaded] = useState(false);

  useEffect(() => {
    if (logoRef.current) {
      gsap.fromTo(logoRef.current,
        { clipPath: 'inset(0 100% 0 0)', opacity: 0 },
        { clipPath: 'inset(0 0% 0 0)', opacity: 1, duration: 1.5, ease: "power2.out" }
      );
    }
  }, []);

  const loginForm = useForm<LoginForm>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      username: "",
      password: "",
    },
  });

  const registerForm = useForm<RegisterForm>({
    resolver: zodResolver(registerSchema),
    defaultValues: {
      username: "",
      email: "",
      password: "",
      confirmPassword: "",
      fullName: "",
      phone: "",
      role: "user",
    },
  });

  const loginMutation = useMutation({
    mutationFn: (data: LoginForm) => apiRequest("/api/auth/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data)
    }),
    onSuccess: (data) => {
      toast({ title: "Success", description: "Logged in successfully" });

      // Store user data
      localStorage.setItem("user", JSON.stringify(data.user));

      // Redirect all users to unified portal
      setLocation("/portal");
    },
    onError: (error: any) => {
      toast({
        variant: "destructive",
        title: "Login Failed",
        description: error.message || "Invalid username or password",
      });
    },
  });

  const registerMutation = useMutation({
    mutationFn: (data: RegisterForm) => apiRequest("/api/auth/register", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data)
    }),
    onSuccess: (data) => {
      toast({ title: "Success", description: "Account created successfully! Please log in." });
      setActiveTab("login");
      loginForm.reset();
    },
    onError: (error: any) => {
      toast({
        variant: "destructive",
        title: "Registration Failed",
        description: error.message || "Failed to create account",
      });
    },
  });

  const handleLogin = (values: LoginForm) => {
    loginMutation.mutate(values);
  };

  const handleRegister = (values: RegisterForm) => {
    registerMutation.mutate(values);
  };

  return (
    <div 
      className="min-h-screen flex items-center justify-center p-4 relative overflow-hidden"
      onMouseMove={(e) => {
        setMousePos({
          x: e.clientX / window.innerWidth,
          y: e.clientY / window.innerHeight
        });
      }}
    >
      {/* Holographic Foil with Deep Valleys and Mountains */}
      <div className="absolute inset-0 overflow-hidden" style={{ zIndex: 0 }}>
        {/* Base deep purple gradient */}
        <div className="absolute inset-0 bg-gradient-to-br from-[#1a0a2e] via-[#2d1b4e] to-[#0f0520]"></div>

        {/* Mountain ridges - light catching peaks */}
        <div 
          className="absolute inset-0 transition-all duration-300 ease-out"
          style={{
            background: `
              linear-gradient(${135 + (mousePos.x - 0.5) * 60}deg, 
                transparent 0%,
                rgba(212, 160, 79, 0.15) ${20 + mousePos.y * 15}%,
                rgba(255, 255, 255, 0.25) ${35 + mousePos.x * 10}%,
                rgba(168, 85, 247, 0.2) ${50 + mousePos.y * 10}%,
                transparent 65%),
              linear-gradient(${225 + (mousePos.y - 0.5) * 40}deg, 
                transparent 10%,
                rgba(236, 72, 153, 0.15) ${30 + mousePos.x * 20}%,
                rgba(255, 255, 255, 0.2) ${45 + mousePos.y * 15}%,
                rgba(56, 189, 248, 0.15) 60%,
                transparent 75%)
            `,
          }}
        ></div>

        {/* Deep valley shadows */}
        <div 
          className="absolute inset-0 transition-all duration-200 ease-out"
          style={{
            background: `
              radial-gradient(ellipse 80% 60% at ${30 + mousePos.x * 40}% ${40 + mousePos.y * 20}%, 
                transparent 0%,
                rgba(15, 5, 30, 0.6) 50%,
                transparent 80%),
              radial-gradient(ellipse 70% 50% at ${70 - mousePos.x * 30}% ${60 - mousePos.y * 20}%, 
                transparent 0%,
                rgba(10, 0, 20, 0.5) 45%,
                transparent 75%)
            `,
          }}
        ></div>

        {/* Holographic shimmer bands - creates the foil effect */}
        <div 
          className="absolute inset-0 transition-all duration-150 ease-out opacity-70"
          style={{
            backgroundImage: `
              repeating-linear-gradient(
                ${90 + (mousePos.x - 0.5) * 30}deg,
                transparent 0px,
                rgba(168, 85, 247, 0.1) 2px,
                rgba(236, 72, 153, 0.08) 4px,
                rgba(212, 160, 79, 0.12) 6px,
                rgba(56, 189, 248, 0.08) 8px,
                transparent 10px
              )
            `,
            transform: `translateX(${(mousePos.x - 0.5) * 20}px) translateY(${(mousePos.y - 0.5) * 20}px)`,
          }}
        ></div>

        {/* Bright spotlight following mouse - mountain peak highlight */}
        <div 
          className="absolute inset-0 transition-all duration-100 ease-out pointer-events-none"
          style={{
            background: `
              radial-gradient(ellipse 40% 30% at ${mousePos.x * 100}% ${mousePos.y * 100}%, 
                rgba(255, 255, 255, 0.25) 0%,
                rgba(212, 160, 79, 0.15) 30%,
                transparent 60%)
            `,
          }}
        ></div>

        {/* Secondary ambient glow */}
        <div 
          className="absolute inset-0 transition-all duration-400 ease-out pointer-events-none opacity-60"
          style={{
            background: `
              radial-gradient(circle 50% at ${100 - mousePos.x * 100}% ${100 - mousePos.y * 100}%, 
                rgba(147, 51, 234, 0.2) 0%,
                transparent 50%)
            `,
          }}
        ></div>
      </div>

      {/* Video Background - Fades in once loaded */}
      <video
        autoPlay
        muted
        loop
        playsInline
        className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-1000 ${isVideoLoaded ? 'opacity-100' : 'opacity-0'}`}
        style={{ zIndex: 1 }}
        onLoadedData={() => setIsVideoLoaded(true)}
      >
        <source src="/hero-video.mp4" type="video/mp4" />
      </video>

      {/* Video Overlay */}
      <div className="absolute inset-0 bg-[#2A0A2A]/50" style={{ zIndex: 2 }}></div>

      <div className="w-full max-w-md relative z-10">
        <div className="text-center mb-8">
          <Link href="/" className="inline-flex items-center justify-center">
              <img
                ref={logoRef}
                src={heroLogo}
                alt="John Barclay Estate & Management"
                className="h-16 sm:h-20 md:h-24 w-auto max-w-[280px] object-contain"
                data-testid="img-login-logo"
              />
          </Link>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>Welcome</CardTitle>
            <CardDescription>Sign in to your account or create a new one</CardDescription>
          </CardHeader>
          <CardContent>
            <Tabs value={activeTab} onValueChange={setActiveTab}>
              <TabsList className="grid w-full grid-cols-2">
                <TabsTrigger value="login">Login</TabsTrigger>
                <TabsTrigger value="register">Register</TabsTrigger>
              </TabsList>

              <TabsContent value="login" className="space-y-4">
                <Form {...loginForm}>
                  <form onSubmit={loginForm.handleSubmit(handleLogin)} className="space-y-4">
                    <FormField
                      control={loginForm.control}
                      name="username"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Username</FormLabel>
                          <FormControl>
                            <Input 
                              placeholder="Enter your username" 
                              data-testid="input-username-login"
                              {...field} 
                            />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={loginForm.control}
                      name="password"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Password</FormLabel>
                          <FormControl>
                            <div className="relative">
                              <Input 
                                type={showLoginPassword ? "text" : "password"}
                                placeholder="Enter your password" 
                                data-testid="input-password-login"
                                {...field} 
                              />
                              <Button
                                type="button"
                                variant="ghost"
                                size="icon"
                                className="absolute right-0 top-0 h-full px-3"
                                onClick={() => setShowLoginPassword(!showLoginPassword)}
                                data-testid="button-toggle-login-password"
                              >
                                {showLoginPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                              </Button>
                            </div>
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <Button
                      type="submit"
                      className="w-full"
                      disabled={loginMutation.isPending}
                      data-testid="button-login"
                    >
                      {loginMutation.isPending ? (
                        <>
                          <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                          Logging in...
                        </>
                      ) : (
                        "Login"
                      )}
                    </Button>
                  </form>
                </Form>

                <div className="space-y-2 mt-4">
                  <Alert>
                    <AlertDescription className="text-sm">
                      <strong>Demo Accounts:</strong>
                      <div className="mt-2 space-y-1">
                        <div className="flex items-center gap-2">
                          <Shield className="h-3 w-3" />
                          Admin: admin / admin123
                        </div>
                        <div className="flex items-center gap-2">
                          <Users className="h-3 w-3" />
                          Agent: agent / agent123
                        </div>
                        <div className="flex items-center gap-2">
                          <User className="h-3 w-3" />
                          Tenant: tenant / tenant123
                        </div>
                      </div>
