import React, { useState, useRef, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import {
  MapPin, TrendingUp, TrendingDown, School, Shield, Train, ShoppingBag, Trees, Building,
  Clock, Star, Users, Home, Heart, Camera, ChevronRight, Award, Activity,
  PoundSterling, Calculator, BarChart, Key, Phone, Mail, Globe
} from 'lucide-react';
import { Link } from 'wouter';
import heroLogo from "@/assets/john-barclay-logo.png";

gsap.registerPlugin(ScrollTrigger);

interface PremiumAreaData {
  postcode: string;
  areaName: string;
  description: string;

  // Current Market Data (2024-2025)
  averagePrice: number;
  pricePerSqFt: number;
  annualGrowth: string;
  fiveYearGrowth: string;
  averageRent1Bed: number;
  averageRent2Bed: number;
  averageRent3Bed: number;
  rentalYield: number;
  timeToSell: number;
  timeToLet: number;

  // Location Intelligence
  transportScore: number;
  schoolRating: number;
  crimeRating: string;
  walkabilityScore: number;

  // Demographics
  demographics: {
    youngProfessionals: number;
    families: number;
    retirees: number;
    international: number;
  };

  // Investment Analysis
  investmentGrade: string;
  capitalGrowthPotential: number;
  liquidityScore: number;
  riskProfile: string;

  // Lifestyle & Amenities
  restaurants: number;
  parks: number;
  gyms: number;
  supermarkets: number;

  // Transport Times
  transportTimes: {
    cityCanaryWharf: string;
    westEnd: string;
    heathrow: string;
    nearestTube: string;
    walkToTube: number;
