  if (bedrooms <= 1 && !furnished) return 100;
  if (bedrooms <= 1 && furnished) return 150;
  if (bedrooms <= 3 && !furnished) return 175;
  if (bedrooms <= 3 && furnished) return 250;
  return 400; // 4+ bedrooms
}

