import { useState, useRef, useCallback } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { insertPropertySchema, type InsertProperty } from '@shared/schema';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';
import { useLocation } from 'wouter';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';
import {
  ArrowLeft, Wand2, Save, Sparkles, Upload,
  Home, DollarSign, MapPin, Bed, Bath, Square,
  Calendar, Shield, Zap, Plus, X, Image, Trash2, GripVertical
} from 'lucide-react';

export default function PropertyCreate() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [isProcessing, setIsProcessing] = useState(false);
  const [aiDescription, setAiDescription] = useState('');
  const [features, setFeatures] = useState<string[]>([]);
  const [newFeature, setNewFeature] = useState('');
  const [images, setImages] = useState<{ file: File; preview: string; isPrimary: boolean }[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Handle image selection
  const handleImageSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);

    const newImages = files.map((file, index) => ({
      file,
      preview: URL.createObjectURL(file),
      isPrimary: images.length === 0 && index === 0
    }));

    setImages(prev => [...prev, ...newImages]);

    // Reset file input
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  }, [images.length]);

  // Remove an image
  const handleRemoveImage = (index: number) => {
    setImages(prev => {
      const newImages = prev.filter((_, i) => i !== index);
      // If removed image was primary, make first image primary
      if (prev[index].isPrimary && newImages.length > 0) {
        newImages[0].isPrimary = true;
      }
      // Revoke object URL to prevent memory leaks
      URL.revokeObjectURL(prev[index].preview);
      return newImages;
    });
  };

  // Set primary image
  const handleSetPrimary = (index: number) => {
    setImages(prev => prev.map((img, i) => ({
      ...img,
      isPrimary: i === index
    })));
  };

  // Upload images to server
  const uploadImages = async (): Promise<string[]> => {
    if (images.length === 0) return [];

    setIsUploading(true);
    const uploadedUrls: string[] = [];

    try {
      // Sort to put primary image first
      const sortedImages = [...images].sort((a, b) => (b.isPrimary ? 1 : 0) - (a.isPrimary ? 1 : 0));

      for (const img of sortedImages) {
        const formData = new FormData();
        formData.append('image', img.file);

        const response = await fetch('/api/crm/upload/property-image', {
          method: 'POST',
          body: formData,
        });

        if (!response.ok) {
          throw new Error('Failed to upload image');
        }

        const result = await response.json();
        uploadedUrls.push(result.url);
      }

      return uploadedUrls;
    } finally {
      setIsUploading(false);
    }
  };

  const form = useForm<any>({
    defaultValues: {
      listingType: 'sale',
      propertyType: 'flat',
      title: '',
      description: '',
      price: 0,
      bedrooms: 1,
      bathrooms: 1,
      receptions: 0,
      squareFootage: 0,
      addressLine1: '',
      addressLine2: '',
      postcode: '',
      tenure: 'leasehold',
      councilTaxBand: '',
      energyRating: '',
      features: [],
      furnished: 'unfurnished',
      viewingArrangements: 'by_appointment'
    }
  });

  const handleAIParse = async () => {
    if (!aiDescription.trim()) {
      toast({
        title: "Please describe the property",
        description: "Enter a natural language description of the property",
        variant: "destructive"
      });
      return;
    }

    setIsProcessing(true);
    try {
      const result = await apiRequest('POST', '/api/crm/properties/parse', {
        description: aiDescription
      });

      // Fill form with parsed data
      if (result.parsed) {
        Object.keys(result.parsed).forEach((key) => {
          if (result.parsed[key] !== undefined && result.parsed[key] !== null) {
            form.setValue(key, result.parsed[key]);
          }
        });

        if (result.parsed.features) {
          setFeatures(result.parsed.features);
        }

        toast({
          title: "Successfully parsed!",
          description: "Property details extracted from your description",
        });
      }
    } catch (error) {
      toast({
        title: "Failed to parse",
        description: "Could not extract property details. Please try again.",
        variant: "destructive"
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAddFeature = () => {
    if (newFeature.trim() && !features.includes(newFeature)) {
      setFeatures([...features, newFeature.trim()]);
      setNewFeature('');
    }
  };

  const handleRemoveFeature = (feature: string) => {
    setFeatures(features.filter(f => f !== feature));
  };

  const onSubmit = async (data: any) => {
    try {
      // First upload images if any
      let imageUrls: string[] = [];
      if (images.length > 0) {
        toast({
          title: "Uploading images...",
          description: `Uploading ${images.length} image(s)`,
        });
        imageUrls = await uploadImages();
      }

      const propertyData = {
        ...data,
        features,
        price: parseFloat(data.price),
        images: imageUrls,
        primaryImage: imageUrls[0] || null
      };

      await apiRequest('POST', '/api/crm/properties', propertyData);

      // Clean up image previews
      images.forEach(img => URL.revokeObjectURL(img.preview));

      toast({
        title: "Property created!",
        description: "The property has been successfully listed.",
      });

      setLocation('/crm/properties');
    } catch (error) {
      toast({
        title: "Failed to create property",
        description: "Please check the form and try again.",
        variant: "destructive"
      });
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="bg-white border-b">
        <div className="px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center space-x-4">
              <Button 
                variant="ghost" 
                onClick={() => setLocation('/crm/dashboard')}
              >
                <ArrowLeft className="mr-2 h-4 w-4" />
                Back to Dashboard
              </Button>
              <h1 className="text-xl font-semibold">Create New Property</h1>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto p-6">
        <Tabs defaultValue="ai" className="space-y-6">
          <TabsList className="grid grid-cols-2 w-full max-w-md">
            <TabsTrigger value="ai" className="flex items-center">
              <Wand2 className="mr-2 h-4 w-4" />
              AI Assistant
            </TabsTrigger>
            <TabsTrigger value="manual" className="flex items-center">
              <Home className="mr-2 h-4 w-4" />
              Manual Entry
            </TabsTrigger>
          </TabsList>

          <TabsContent value="ai" className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Describe the Property</CardTitle>
                <CardDescription>
                  Use natural language to describe the property. Our AI will extract all the details for you.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <Textarea
                  placeholder="Example: Beautiful 2 bedroom flat in Maida Vale W9, recently renovated with modern kitchen and bathroom. £650,000 leasehold with 125 years remaining. Features include wooden floors, high ceilings, and a private balcony. Close to Paddington station and local shops. Perfect for first-time buyers or investors. EPC rating B, council tax band D."
                  className="min-h-[200px]"
                  value={aiDescription}
                  onChange={(e) => setAiDescription(e.target.value)}
                />

                <div className="flex justify-between items-center">
                  <div className="text-sm text-gray-600">
                    Tip: Include as many details as possible - price, location, features, etc.
                  </div>
                  <Button
                    onClick={handleAIParse}
                    disabled={isProcessing}
                    className="bg-gradient-to-r from-purple-600 to-blue-600 hover:from-purple-700 hover:to-blue-700"
                  >
                    {isProcessing ? (
                      <>Processing...</>
                    ) : (
                      <>
                        <Sparkles className="mr-2 h-4 w-4" />
                        Extract Details with AI
                      </>
                    )}
                  </Button>
                </div>
              </CardContent>
            </Card>

            {form.getValues().title && (
              <Card>
                <CardHeader>
                  <CardTitle>Extracted Property Details</CardTitle>
                  <CardDescription>Review and edit the details extracted by AI</CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <p className="text-sm font-medium mb-1">Title</p>
                      <p className="text-sm text-gray-600">{form.getValues().title}</p>
                    </div>
                    <div>
                      <p className="text-sm font-medium mb-1">Price</p>
                      <p className="text-sm text-gray-600">£{form.getValues().price?.toLocaleString()}</p>
                    </div>
                    <div>
                      <p className="text-sm font-medium mb-1">Location</p>
                      <p className="text-sm text-gray-600">{form.getValues().postcode}</p>
                    </div>
                    <div>
                      <p className="text-sm font-medium mb-1">Bedrooms</p>
                      <p className="text-sm text-gray-600">{form.getValues().bedrooms}</p>
                    </div>
                  </div>
                  <Button 
                    className="mt-4 w-full"
                    onClick={() => {
                      const tabsList = document.querySelector('[data-value="manual"]') as HTMLElement;
                      if (tabsList) tabsList.click();
                    }}
                  >
                    Review Full Details
                  </Button>
                </CardContent>
              </Card>
            )}
          </TabsContent>

          <TabsContent value="manual">
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                {/* Basic Information */}
                <Card>
                  <CardHeader>
                    <CardTitle>Basic Information</CardTitle>
                  </CardHeader>
                  <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <FormField
                      control={form.control}
                      name="listingType"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Listing Type</FormLabel>
                          <Select onValueChange={field.onChange} value={field.value}>
                            <FormControl>
                              <SelectTrigger>
                                <SelectValue placeholder="Select type" />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                              <SelectItem value="sale">For Sale</SelectItem>
                              <SelectItem value="rental">For Rent</SelectItem>
                            </SelectContent>
                          </Select>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="propertyType"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Property Type</FormLabel>
                          <Select onValueChange={field.onChange} value={field.value}>
                            <FormControl>
                              <SelectTrigger>
                                <SelectValue placeholder="Select property type" />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                              <SelectItem value="flat">Flat</SelectItem>
                              <SelectItem value="house">House</SelectItem>
                              <SelectItem value="maisonette">Maisonette</SelectItem>
                              <SelectItem value="penthouse">Penthouse</SelectItem>
                              <SelectItem value="studio">Studio</SelectItem>
                            </SelectContent>
                          </Select>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="title"
                      render={({ field }) => (
                        <FormItem className="md:col-span-2">
                          <FormLabel>Property Title</FormLabel>
                          <FormControl>
                            <Input {...field} placeholder="e.g., 2 Bed Flat in Maida Vale" />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="price"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Price (£)</FormLabel>
                          <FormControl>
                            <Input {...field} type="number" placeholder="650000" />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="bedrooms"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Bedrooms</FormLabel>
                          <FormControl>
                            <Input {...field} type="number" min="0" />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="bathrooms"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Bathrooms</FormLabel>
                          <FormControl>
                            <Input {...field} type="number" min="0" />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="squareFootage"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Square Footage</FormLabel>
                          <FormControl>
                            <Input {...field} type="number" placeholder="850" />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </CardContent>
                </Card>

                {/* Location */}
                <Card>
                  <CardHeader>
                    <CardTitle>Location</CardTitle>
                  </CardHeader>
                  <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <FormField
                      control={form.control}
                      name="addressLine1"
                      render={({ field }) => (
                        <FormItem className="md:col-span-2">
                          <FormLabel>Address Line 1</FormLabel>
                          <FormControl>
                            <Input {...field} placeholder="123 Example Street" />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="addressLine2"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Address Line 2</FormLabel>
                          <FormControl>
                            <Input {...field} placeholder="Apartment 4B" />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="postcode"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Postcode</FormLabel>
                          <FormControl>
                            <Input {...field} placeholder="W9 1AA" />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </CardContent>
                </Card>

                {/* Features */}
                <Card>
                  <CardHeader>
                    <CardTitle>Features</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-4">
                      <div className="flex gap-2">
                        <Input
                          value={newFeature}
                          onChange={(e) => setNewFeature(e.target.value)}
                          placeholder="Add a feature (e.g., Garden, Parking)"
                          onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), handleAddFeature())}
                        />
                        <Button type="button" onClick={handleAddFeature}>
                          <Plus className="h-4 w-4" />
                        </Button>
                      </div>

                      <div className="flex flex-wrap gap-2">
                        {features.map((feature) => (
                          <Badge key={feature} variant="secondary" className="px-3 py-1">
                            {feature}
                            <button
                              type="button"
                              onClick={() => handleRemoveFeature(feature)}
                              className="ml-2"
                            >
                              <X className="h-3 w-3" />
                            </button>
                          </Badge>
                        ))}
                      </div>
                    </div>
                  </CardContent>
                </Card>

                {/* Description */}
                <Card>
                  <CardHeader>
                    <CardTitle>Description</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <FormField
                      control={form.control}
                      name="description"
                      render={({ field }) => (
                        <FormItem>
                          <FormControl>
                            <Textarea
                              {...field}
                              className="min-h-[150px]"
                              placeholder="Detailed property description..."
                            />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </CardContent>
                </Card>

                {/* Property Images */}
                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center">
                      <Image className="h-5 w-5 mr-2" />
                      Property Images
                    </CardTitle>
                    <CardDescription>
                      Upload high-quality images. The first image will be the primary image shown on portals.
                    </CardDescription>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-4">
                      {/* Upload Area */}
                      <div
                        className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center hover:border-purple-400 transition-colors cursor-pointer"
                        onClick={() => fileInputRef.current?.click()}
                      >
                        <input
                          ref={fileInputRef}
                          type="file"
                          accept="image/*"
                          multiple
                          className="hidden"
                          onChange={handleImageSelect}
                        />
                        <Upload className="h-10 w-10 mx-auto text-gray-400 mb-4" />
                        <p className="text-sm text-gray-600 mb-2">
                          Click to upload or drag and drop
                        </p>
                        <p className="text-xs text-gray-400">
                          PNG, JPG, WEBP up to 10MB each. Minimum 5 images recommended.
                        </p>
                      </div>

                      {/* Image Preview Grid */}
                      {images.length > 0 && (
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                          {images.map((img, index) => (
                            <div
                              key={index}
                              className={`relative group rounded-lg overflow-hidden border-2 ${
                                img.isPrimary ? 'border-purple-500 ring-2 ring-purple-200' : 'border-gray-200'
                              }`}
                            >
                              <img
                                src={img.preview}
                                alt={`Property image ${index + 1}`}
                                className="w-full h-32 object-cover"
                              />

                              {/* Primary Badge */}
                              {img.isPrimary && (
                                <div className="absolute top-2 left-2">
                                  <Badge className="bg-purple-600 text-white text-xs">
                                    Primary
                                  </Badge>
                                </div>
                              )}

                              {/* Hover Actions */}
                              <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                                {!img.isPrimary && (
                                  <Button
                                    type="button"
                                    size="sm"
                                    variant="secondary"
                                    onClick={() => handleSetPrimary(index)}
                                    className="text-xs"
                                  >
                                    Set Primary
                                  </Button>
                                )}
                                <Button
                                  type="button"
                                  size="sm"
                                  variant="destructive"
                                  onClick={() => handleRemoveImage(index)}
                                >
                                  <Trash2 className="h-4 w-4" />
                                </Button>
                              </div>
                            </div>
                          ))}
                        </div>
                      )}

                      {/* Image Count */}
                      <div className="flex justify-between items-center text-sm text-gray-500">
                        <span>{images.length} image(s) selected</span>
                        {images.length > 0 && images.length < 5 && (
                          <span className="text-yellow-600">
                            Add {5 - images.length} more for better listing performance
                          </span>
                        )}
                      </div>
                    </div>
                  </CardContent>
                </Card>

                {/* Submit */}
                <div className="flex justify-end space-x-4">
                  <Button 
                    type="button" 
                    variant="outline"
                    onClick={() => setLocation('/crm/dashboard')}
                  >
                    Cancel
                  </Button>
                  <Button type="submit">
                    <Save className="mr-2 h-4 w-4" />
                    Create Property
                  </Button>
                </div>
              </form>
            </Form>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

