const getChannelIcon = (channel: string) => {
  switch (channel) {
    case 'email': return <Mail className="h-4 w-4" />;
    case 'sms': return <Smartphone className="h-4 w-4" />;
    case 'whatsapp': return <MessagesSquare className="h-4 w-4" />;
    case 'phone': return <Phone className="h-4 w-4" />;
    default: return <MessageSquare className="h-4 w-4" />;
  }
};

const getStatusColor = (status: string) => {
  switch (status) {
    case 'open': return 'bg-blue-100 text-blue-800';
    case 'pending': return 'bg-yellow-100 text-yellow-800';
    case 'resolved': return 'bg-green-100 text-green-800';
    case 'closed': return 'bg-gray-100 text-gray-800';
    default: return 'bg-gray-100 text-gray-800';
  }
};

const getPriorityColor = (priority: string) => {
  switch (priority) {
    case 'urgent': return 'bg-red-100 text-red-800';
    case 'high': return 'bg-orange-100 text-orange-800';
    case 'normal': return 'bg-blue-100 text-blue-800';
    case 'low': return 'bg-gray-100 text-gray-800';
    default: return 'bg-gray-100 text-gray-800';
  }
};

const formatTimeAgo = (date: Date) => {
  const seconds = Math.floor((new Date().getTime() - date.getTime()) / 1000);
  if (seconds < 60) return 'Just now';
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
};

export default function CommunicationHub() {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const [activeTab, setActiveTab] = useState('inbox');
  const [selectedConversation, setSelectedConversation] = useState<any>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterChannel, setFilterChannel] = useState('all');
  const [replyText, setReplyText] = useState('');

  // Template dialog state
  const [showTemplateDialog, setShowTemplateDialog] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState<any>(null);
  const [templateForm, setTemplateForm] = useState({
    templateName: '',
    templateType: 'email',
    subject: '',
    content: ''
  });

  // Campaign dialog state
  const [showCampaignDialog, setShowCampaignDialog] = useState(false);
  const [campaignForm, setCampaignForm] = useState({
    name: '',
    description: '',
    campaignType: 'email',
    targetAudience: 'all',
    subject: '',
    content: '',
    scheduleDate: '',
    scheduleTime: ''
  });

  // Filter conversations
  const filteredConversations = mockConversations.filter(conv => {
    const matchesSearch = searchQuery === '' ||
      conv.contactName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      conv.lastMessagePreview.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesStatus = filterStatus === 'all' || conv.status === filterStatus;
    const matchesChannel = filterChannel === 'all' || conv.channel === filterChannel;
    return matchesSearch && matchesStatus && matchesChannel;
  });

  const handleSendReply = () => {
    if (!replyText.trim()) return;

    toast({
      title: 'Message sent',
      description: 'Your reply has been sent successfully.'
    });
    setReplyText('');
  };

  const handleSaveTemplate = () => {
    toast({
      title: editingTemplate ? 'Template updated' : 'Template created',
      description: `Template "${templateForm.templateName}" has been saved.`
    });
    setShowTemplateDialog(false);
    setEditingTemplate(null);
    setTemplateForm({
      templateName: '',
      templateType: 'email',
      subject: '',
      content: ''
    });
  };

  const handleCreateCampaign = () => {
    toast({
      title: 'Campaign created',
      description: `Campaign "${campaignForm.name}" has been created.`
    });
    setShowCampaignDialog(false);
    setCampaignForm({
      name: '',
      description: '',
      campaignType: 'email',
      targetAudience: 'all',
      subject: '',
      content: '',
      scheduleDate: '',
      scheduleTime: ''
    });
  };

  const openEditTemplate = (template: any) => {
    setEditingTemplate(template);
    setTemplateForm({
      templateName: template.templateName,
      templateType: template.templateType,
      subject: template.subject,
      content: template.content
    });
    setShowTemplateDialog(true);
  };

  return (
    <div className="min-h-screen bg-gray-50">
