                        <SelectContent>
                          <SelectItem value="all">All Channels</SelectItem>
                          <SelectItem value="email">Email</SelectItem>
                          <SelectItem value="sms">SMS</SelectItem>
                          <SelectItem value="whatsapp">WhatsApp</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  </div>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y max-h-[600px] overflow-y-auto">
                    {filteredConversations.map((conversation) => (
                      <div
                        key={conversation.id}
                        className={`p-4 cursor-pointer hover:bg-gray-50 ${
                          selectedConversation?.id === conversation.id ? 'bg-blue-50' : ''
                        }`}
                        onClick={() => setSelectedConversation(conversation)}
                      >
                        <div className="flex items-start justify-between mb-2">
                          <div className="flex items-center space-x-2">
                            <div className="w-8 h-8 rounded-full bg-gray-200 flex items-center justify-center">
                              <User className="h-4 w-4 text-gray-500" />
                            </div>
                            <div>
                              <p className="font-medium text-sm">{conversation.contactName}</p>
                              <div className="flex items-center space-x-1 text-xs text-gray-500">
                                {getChannelIcon(conversation.channel)}
                                <span>{formatTimeAgo(conversation.lastMessageAt)}</span>
                              </div>
                            </div>
                          </div>
                          {conversation.unreadCount > 0 && (
                            <Badge className="bg-blue-500">{conversation.unreadCount}</Badge>
                          )}
                        </div>
                        <p className="text-sm text-gray-600 line-clamp-2 mb-2">
                          {conversation.lastMessagePreview}
                        </p>
                        <div className="flex items-center justify-between">
                          <div className="flex space-x-1">
                            <Badge variant="outline" className={getStatusColor(conversation.status)}>
                              {conversation.status}
                            </Badge>
                            {conversation.priority === 'high' && (
                              <Badge variant="outline" className={getPriorityColor(conversation.priority)}>
                                {conversation.priority}
                              </Badge>
                            )}
                          </div>
                          {conversation.propertyTitle && (
                            <span className="text-xs text-gray-500 truncate max-w-[100px]">
                              {conversation.propertyTitle}
                            </span>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>

              {/* Conversation Detail */}
              <Card className="lg:col-span-2">
                {selectedConversation ? (
                  <>
                    <CardHeader className="border-b">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-3">
                          <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center">
                            <User className="h-5 w-5 text-gray-500" />
                          </div>
                          <div>
                            <CardTitle className="text-lg">{selectedConversation.contactName}</CardTitle>
                            <CardDescription>
                              {selectedConversation.contactEmail} | {selectedConversation.contactPhone}
                            </CardDescription>
                          </div>
                        </div>
                        <div className="flex items-center space-x-2">
                          <Button variant="ghost" size="icon">
                            <Star className="h-4 w-4" />
                          </Button>
                          <Button variant="ghost" size="icon">
                            <Archive className="h-4 w-4" />
                          </Button>
                          <Button variant="ghost" size="icon">
                            <MoreVertical className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>
                      {selectedConversation.propertyTitle && (
                        <div className="flex items-center mt-2 text-sm text-gray-600">
                          <Building2 className="h-4 w-4 mr-1" />
                          {selectedConversation.propertyTitle}
                        </div>
                      )}
                      <div className="flex flex-wrap gap-1 mt-2">
                        {selectedConversation.tags.map((tag: string) => (
                          <Badge key={tag} variant="secondary" className="text-xs">
                            <Tag className="h-3 w-3 mr-1" />
                            {tag}
                          </Badge>
                        ))}
                      </div>
                    </CardHeader>
                    <CardContent className="p-0">
                      {/* Messages */}
                      <div className="h-[400px] overflow-y-auto p-4 space-y-4">
                        {mockMessages.map((message) => (
                          <div
                            key={message.id}
                            className={`flex ${message.direction === 'outbound' ? 'justify-end' : 'justify-start'}`}
                          >
                            <div
                              className={`max-w-[80%] p-3 rounded-lg ${
                                message.direction === 'outbound'
                                  ? 'bg-blue-500 text-white'
                                  : 'bg-gray-100 text-gray-800'
                              }`}
                            >
                              <p className="text-sm whitespace-pre-wrap">{message.content}</p>
                              <div className={`flex items-center justify-end mt-1 space-x-1 text-xs ${
                                message.direction === 'outbound' ? 'text-blue-100' : 'text-gray-500'
                              }`}>
                                <span>{formatTimeAgo(message.sentAt)}</span>
                                {message.direction === 'outbound' && (
                                  <CheckCircle className="h-3 w-3" />
                                )}
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>

                      {/* Reply Box */}
                      <div className="border-t p-4">
                        <div className="flex items-center space-x-2 mb-2">
                          <Button variant="ghost" size="sm">
                            <Mail className="h-4 w-4" />
                          </Button>
                          <Button variant="ghost" size="sm">
                            <Smartphone className="h-4 w-4" />
                          </Button>
                          <Button variant="ghost" size="sm">
                            <MessagesSquare className="h-4 w-4" />
                          </Button>
                        </div>
                        <div className="flex space-x-2">
                          <Textarea
                            placeholder="Type your reply..."
                            className="flex-1 resize-none"
                            rows={3}
                            value={replyText}
                            onChange={(e) => setReplyText(e.target.value)}
                          />
                        </div>
                        <div className="flex justify-end mt-2">
                          <Button onClick={handleSendReply}>
                            <Send className="h-4 w-4 mr-2" />
